import { mkdir, writeFile } from "node:fs/promises";
import { format } from "prettier";
import { readKnowledge, validateKnowledge } from "./knowledge.mjs";
const data = validateKnowledge(await readKnowledge());
await mkdir("src/mock", { recursive: true });
const generated =
  "// Generated by npm run knowledge:sync. Edit .project records, not this file.\n";
async function save(file, source) {
  await writeFile(
    `src/mock/${file}.ts`,
    await format(generated + source, { parser: "typescript" }),
  );
}
for (const [group, file, type, exportName] of [
  ["components", "components", "ArchitectureNode", "nodes"],
  ["tasks", "tasks", "Task", "tasks"],
  ["changes", "activity", "Change", "changes"],
  ["decisions", "decisions", "Decision", "decisions"],
]) {
  await save(
    file,
    `import type { ${type} } from '@/types';\n` +
      data.files[group]
        .map((f, i) => `import record${i} from '../../.project/${f}';`)
        .join("\n") +
      `\nexport const ${exportName} = [${data.files[group].map((_, i) => `record${i}`).join(", ")}] as ${type}[];\n`,
  );
}
await save(
  "project",
  `import type { Snapshot } from '@/types';
import projectRecord from '../../.project/project.json';
import projectsRecord from '../../.project/projects.json';
import developersRecord from '../../.project/developers.json';
import notificationsRecord from '../../.project/notifications.json';
import overviewRecord from '../../.project/overview.json';
import manifest from '../../.project/manifest.json';
export const project = projectRecord as Snapshot['project'];
export const projects = projectsRecord as Snapshot['projects'];
export const developers = developersRecord as Snapshot['developers'];
export const notifications = notificationsRecord as Snapshot['notifications'];
export const overview = overviewRecord as Snapshot['overview'];
export const knowledge: Snapshot['knowledge'] = { schemaVersion: manifest.schemaVersion, knowledgeRevision: manifest.knowledgeRevision, recordedAt: manifest.recordedAt };
`,
);
await save(
  "architecture",
  `import type { ArchitectureEdge, ArchitectureFlow } from '@/types';
import record from '../../.project/architecture.json';
export const edges = record.edges as ArchitectureEdge[];
export const flows = record.flows as ArchitectureFlow[];`,
);
await save(
  "board",
  `import type { Milestone } from '@/types';
import records from '../../.project/milestones.json';
export const milestones = records as Milestone[];
export { tasks } from './tasks';`,
);
await save(
  "planner",
  `import record from '../../.project/planner.json';
export const planner = record;`,
);
console.log(
  "Synchronized typed adapters in src/mock from all discovered knowledge records.",
);
